corrected_code:
const LaunchDarkly = require('launchdarkly-node-server-sdk');
const ldClient = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);

router.get('/api/flags/evaluate', verifyAuth, async (req, res) => {
  const flagKey = req.query.flagKey;
  const userKey = req.user.id;

  const ldUser = {
    key: userKey,
    custom: {
      role: req.user.role,
      tier: req.user.tier
    }
  };
  const flagValue = await ldClient.variation(flagKey, ldUser, false);

  res.json({ flagKey, userKey, value: flagValue });
});
